[{"name":"Write","arguments":{"content":""""Warehouse inventory CLI.

The append-only log named by --log is the source of truth; the snapshot at
LOG + ".state" is a derived cache.  `in`/`out` append one event and update
the snapshot; `rebuild` refolds the whole log into a fresh snapshot.  When
a log exists but its snapshot is gone, commands that need the snapshot
refuse and point at rebuild rather than guessing.
"""
import argparse
import sys

from eventlog import EventLog
from snapshot import Snapshot, fold

EXIT_REFUSED = 1
EXIT_USAGE = 2


def die(message, code):
    print(message, file=sys.stderr)
    sys.exit(code)


def parse_qty(raw):
    """A quantity must be a positive integer; anything else is a usage error."""
    try:
        qty = int(raw)
    except ValueError:
        die("qty must be a positive integer, got %r" % (raw,), EXIT_USAGE)
    if qty <= 0:
        die("qty must be a positive integer, got %r" % (raw,), EXIT_USAGE)
    return qty


def require_snapshot(log, snap):
    """A log without its snapshot is refused: no guessing, no writes."""
    if log.exists() and not snap.exists():
        die("snapshot %s is missing; run rebuild first" % snap.path, EXIT_REFUSED)


def load_current(snap):
    """Load the snapshot if there is one; a fresh start is just empty stock."""
    if not snap.exists():
        return
    try:
        snap.load()
    except (ValueError, KeyError, TypeError):
        die("snapshot %s is corrupt; run rebuild first" % snap.path, EXIT_REFUSED)


def cmd_stock(log, snap, sku):
    require_snapshot(log, snap)
    load_current(snap)
    if sku is None:
        for name, qty in sorted(snap.counts.items()):
            if qty > 0:
                print("%s: %d" % (name, qty))
    else:
        print(snap.get(sku))


def cmd_move(op, log, snap, sku, qty):
    """Append one event and update the snapshot -- or refuse before writing."""
    require_snapshot(log, snap)
    load_current(snap)
    if op == "out":
        held = snap.get(sku)
        if qty > held:
            die("refused: %s holds %d, cannot draw %d" % (sku, held, qty),
                EXIT_REFUSED)
    log.append(op, sku, qty)
    snap.apply(op, sku, qty)
    snap.save()


def cmd_history(log, sku):
    """History reads the log directly, so it works without a snapshot."""
    for ev in log.events():
        if ev["sku"] == sku:
            print("%s %d" % (ev["op"], ev["qty"]))


def cmd_rebuild(log, snap):
    snap.counts, total = fold(log.events())
    snap.save()
    print("rebuilt %d events" % total)


def build_parser():
    parser = argparse.ArgumentParser(
        prog="inventory.py",
        description="Warehouse stock tool backed by an append-only event log.")
    parser.add_argument("--log", required=True, metavar="FILE",
                        help="append-only event log; snapshot lives at FILE.state")
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    p = sub.add_parser("stock", help="list stock, or show one SKU's count")
    p.add_argument("sku", nargs="?", help="show only this SKU (default: all)")

    for name, help_text in (("in", "receive stock"), ("out", "issue stock")):
        p = sub.add_parser(name, help=help_text)
        p.add_argument("sku")
        p.add_argument("qty", help="quantity, a positive integer")

    p = sub.add_parser("history", help="show one SKU's events, read from the log")
    p.add_argument("sku")
    sub.add_parser("rebuild", help="refold the whole log into a fresh snapshot")
    return parser


def main(argv=None):
    args = build_parser().parse_args(argv)
    log = EventLog(args.log)
    snap = Snapshot(args.log)
    if args.command == "stock":
        cmd_stock(log, snap, args.sku)
    elif args.command == "history":
        cmd_history(log, args.sku)
    elif args.command == "rebuild":
        cmd_rebuild(log, snap)
    else:
        cmd_move(args.command, log, snap, args.sku, parse_qty(args.qty))


if __name__ == "__main__":
    main()
